// lib/dz-sports-archive.js
function searchPlayerInfo(name = "") {
  const q = name.trim().toLowerCase();
  if (!q) return { found: false, player: null, key: "" };
  for (const [key2, player] of Object.entries(FAMOUS_PLAYERS)) {
    if (key2.toLowerCase().includes(q) || q.includes(key2.toLowerCase())) {
      return { found: true, player, key: key2 };
    }
    if (player.aliases?.some((a) => a.toLowerCase().includes(q) || q.includes(a.toLowerCase()))) {
      return { found: true, player, key: key2 };
    }
  }
  return { found: false, player: null, key: "" };
}
function getWorldCupWins(teamName = "") {
  const q = teamName.trim().toLowerCase();
  const wins = WORLD_CUP_HISTORY.filter(
    (w) => w.winner.toLowerCase().includes(q) || q.includes(w.winner.toLowerCase())
  );
  if (!wins.length && (q.includes("\u0623\u0644\u0645\u0627\u0646\u064A\u0627") || q.includes("germany"))) {
    return WORLD_CUP_HISTORY.filter((w) => w.winner.includes("\u0623\u0644\u0645\u0627\u0646\u064A\u0627"));
  }
  return wins;
}
function getLastChampion(competition = "worldcup") {
  const comp = competition.toLowerCase();
  if (comp.includes("world") || comp.includes("\u0645\u0648\u0646\u062F\u064A\u0627\u0644") || comp.includes("\u0639\u0627\u0644\u0645")) {
    return WORLD_CUP_HISTORY[0];
  }
  if (comp.includes("afcon") || comp.includes("\u0623\u0641\u0631\u064A\u0642\u064A\u0627") || comp.includes("\u0643\u0627\u0646")) {
    return AFCON_HISTORY[0];
  }
  if (comp.includes("champion") || comp.includes("\u0623\u0628\u0637\u0627\u0644 \u0623\u0648\u0631\u0648\u0628\u0627") || comp.includes("champions league")) {
    return UCL_HISTORY[0];
  }
  return null;
}
function getTeamTrophies(teamName = "", competition = "") {
  const q = teamName.trim().toLowerCase();
  const comp = competition.toLowerCase();
  for (const [key2, data] of Object.entries(TEAM_TROPHIES)) {
    if (key2.toLowerCase().includes(q) || q.includes(key2.toLowerCase())) {
      if (comp.includes("\u0639\u0627\u0644\u0645") || comp.includes("\u0645\u0648\u0646\u062F\u064A\u0627\u0644") || comp.includes("world")) {
        return { team: key2, competition: "\u0643\u0623\u0633 \u0627\u0644\u0639\u0627\u0644\u0645", titles: data.worldCup || [], note: data.note };
      }
      if (comp.includes("\u0623\u0641\u0631\u064A\u0642") || comp.includes("\u0643\u0627\u0646") || comp.includes("afcon")) {
        return { team: key2, competition: "\u0643\u0623\u0633 \u0623\u0645\u0645 \u0623\u0641\u0631\u064A\u0642\u064A\u0627", titles: data.afcon || [], note: data.note };
      }
      if (comp.includes("\u0623\u0648\u0631\u0648\u0628") || comp.includes("\u064A\u0648\u0631\u0648") || comp.includes("euro")) {
        return { team: key2, competition: "\u0628\u0637\u0648\u0644\u0629 \u0623\u0648\u0631\u0648\u0628\u0627", titles: data.euro || [], note: data.note };
      }
      return { team: key2, competition: "\u0643\u0644 \u0627\u0644\u0623\u0644\u0642\u0627\u0628", titles: [...data.worldCup || [], ...data.afcon || [], data.euro || []], note: data.note };
    }
  }
  const wcWins = getWorldCupWins(teamName);
  if (wcWins.length) {
    return {
      team: teamName,
      competition: "\u0643\u0623\u0633 \u0627\u0644\u0639\u0627\u0644\u0645",
      titles: wcWins.map((w) => ({ year: w.year, host: w.host, score: w.score })),
      note: `${teamName} \u0641\u0627\u0632\u062A \u0628\u0643\u0623\u0633 \u0627\u0644\u0639\u0627\u0644\u0645 ${wcWins.length} \u0645\u0631\u0629/\u0645\u0631\u0627\u062A`
    };
  }
  const afconWins = AFCON_HISTORY.filter(
    (w) => w.winner.toLowerCase().includes(q) || q.includes(w.winner.toLowerCase())
  );
  if (afconWins.length) {
    return {
      team: teamName,
      competition: "\u0643\u0623\u0633 \u0623\u0645\u0645 \u0623\u0641\u0631\u064A\u0642\u064A\u0627",
      titles: afconWins.map((w) => ({ year: w.year, host: w.host, score: w.score })),
      note: `${teamName} \u0641\u0627\u0632\u062A \u0628\u0643\u0623\u0633 \u0623\u0645\u0645 \u0623\u0641\u0631\u064A\u0642\u064A\u0627 ${afconWins.length} \u0645\u0631\u0629/\u0645\u0631\u0627\u062A`
    };
  }
  return null;
}
function buildPlayerInfoBlock(playerKey, player) {
  const lines = [
    `\u2501\u2501\u2501 \u26BD \u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0627\u0644\u0644\u0627\u0639\u0628: **${playerKey}** ${player.flag || ""} \u2501\u2501\u2501
`,
    `\u{1F464} **\u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0643\u0627\u0645\u0644:** ${player.fullName || playerKey}`,
    `\u{1F30D} **\u0627\u0644\u062C\u0646\u0633\u064A\u0629:** ${player.nationality || "\u2014"} ${player.flag || ""}`,
    `\u{1F3DF}\uFE0F **\u0627\u0644\u0646\u0627\u062F\u064A \u0627\u0644\u062D\u0627\u0644\u064A:** ${player.currentClub || "\u2014"}`,
    `\u{1F3C6} **\u0627\u0644\u062F\u0648\u0631\u064A:** ${player.currentLeague || "\u2014"}`,
    `\u{1F3BD} **\u0627\u0644\u0645\u0631\u0643\u0632:** ${player.position || "\u2014"}`,
    player.dob ? `\u{1F4C5} **\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0645\u064A\u0644\u0627\u062F:** ${player.dob}` : ""
  ].filter(Boolean);
  if (player.transferHistory?.length) {
    lines.push(`
### \u{1F504} \u0633\u062C\u0644 \u0627\u0644\u0627\u0646\u062A\u0642\u0627\u0644\u0627\u062A`);
    for (const t of player.transferHistory.slice(-4)) {
      const fee = t.fee ? ` (${t.fee})` : "";
      lines.push(`\u2022 **${t.season || "?"}:** ${t.from} \u2190 **${t.to}**${fee} \u2014 ${t.type || ""}`);
    }
  }
  if (player.achievements) {
    lines.push(`
\u{1F3C5} **\u0627\u0644\u0625\u0646\u062C\u0627\u0632\u0627\u062A:** ${player.achievements}`);
  }
  if (player.note) {
    lines.push(`
\u{1F4CC} **\u0645\u0644\u0627\u062D\u0638\u0629:** ${player.note}`);
  }
  return lines.join("\n");
}
function buildWorldCupTrophyBlock(teamName, wins) {
  if (!wins.length) {
    return `\u26A0\uFE0F \u0644\u0645 \u064A\u064F\u0639\u062B\u0631 \u0639\u0644\u0649 \u0623\u0644\u0642\u0627\u0628 \u0643\u0623\u0633 \u0627\u0644\u0639\u0627\u0644\u0645 \u0644\u0640 **${teamName}** \u0641\u064A \u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A.`;
  }
  const lines = [
    `\u2501\u2501\u2501 \u{1F3C6} **${teamName}** \u0648\u0643\u0623\u0633 \u0627\u0644\u0639\u0627\u0644\u0645 \u2501\u2501\u2501
`,
    `\u2705 **\u0639\u062F\u062F \u0627\u0644\u0623\u0644\u0642\u0627\u0628:** ${wins.length} \u0644\u0642\u0628`,
    ``
  ];
  for (const w of wins) {
    lines.push(`### ${w.flag} **${w.year}** \u2014 ${w.host}`);
    lines.push(`\u{1F4CA} \u0627\u0644\u0646\u0647\u0627\u0626\u064A: ${w.winner} **${w.score}** ${w.runner}`);
    lines.push(``);
  }
  const trophyData = Object.entries(TEAM_TROPHIES).find(
    ([k]) => k.toLowerCase().includes(teamName.toLowerCase()) || teamName.toLowerCase().includes(k.toLowerCase())
  );
  if (trophyData?.[1]?.note) {
    lines.push(`\u{1F4CC} ${trophyData[1].note}`);
  }
  return lines.join("\n");
}
function buildAfconTrophyBlock(teamName, wins) {
  if (!wins.length) {
    return `\u26A0\uFE0F \u0644\u0645 \u064A\u064F\u0639\u062B\u0631 \u0639\u0644\u0649 \u0623\u0644\u0642\u0627\u0628 \u0643\u0623\u0633 \u0623\u0645\u0645 \u0623\u0641\u0631\u064A\u0642\u064A\u0627 \u0644\u0640 **${teamName}** \u0641\u064A \u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A.`;
  }
  const lines = [
    `\u2501\u2501\u2501 \u{1F3C6} **${teamName}** \u0648\u0643\u0623\u0633 \u0623\u0645\u0645 \u0623\u0641\u0631\u064A\u0642\u064A\u0627 \u2501\u2501\u2501
`,
    `\u2705 **\u0639\u062F\u062F \u0627\u0644\u0623\u0644\u0642\u0627\u0628:** ${wins.length} \u0644\u0642\u0628`,
    ``
  ];
  for (const w of wins) {
    lines.push(`### ${w.flag} **${w.year}** \u2014 ${w.host}`);
    lines.push(`\u{1F4CA} \u0627\u0644\u0646\u0647\u0627\u0626\u064A: **${w.score}** \u0623\u0645\u0627\u0645 ${w.runner}`);
    if (w.dzGoalscorer) lines.push(`\u26BD \u0647\u062F\u0627\u0641 \u0627\u0644\u0646\u0647\u0627\u0626\u064A: **${w.dzGoalscorer}**`);
    lines.push(``);
  }
  return lines.join("\n");
}
