    lines.push("\u{1F524} **\u0627\u0644\u0641\u0631\u0627\u0646\u0643\u0648-\u0639\u0631\u0628\u064A** \u2014 \u0645\u0632\u064A\u062C \u0639\u0631\u0628\u064A/\u0641\u0631\u0646\u0633\u064A \u0627\u0644\u0645\u062A\u062F\u0627\u0648\u0644 \u062C\u062F\u0627\u064B \u0639\u0646\u062F \u0627\u0644\u062C\u0632\u0627\u0626\u0631\u064A\u064A\u0646:");
