  lines.push('  \u2465 \u0644\u0627 \u062A\u0628\u062F\u0623 \u0628\u0640 "\u0628\u0627\u0644\u0637\u0628\u0639" \u0623\u0648 "\u0628\u0627\u0644\u0641\u0639\u0644" \u2014 \u0627\u0628\u062F\u0623 \u0628\u0627\u0644\u062F\u0627\u0631\u062C\u0629 \u0645\u0628\u0627\u0634\u0631\u0629');
