try {
  if (!existsSync2(DATA_DIR2)) mkdirSync2(DATA_DIR2, { recursive: true });
} catch {
}
var BREAKING_TITLE_PREFIXES = [
  /^عاجل\s*[:\-–|،]/i,
  /^\[عاجل\]/i,
  /^🔴\s*عاجل/,
  /^⚡\s*عاجل/,
  /^عاجل\s+عاجل/i,
  /^breaking\s*[:\-–|]/i,
  /^flash\s*[:\-–|]/i,
  /^actu[\s-]flash/i,
  /^urgent\s*[:\-–|]/i,
  /^خبر\s+عاجل\s*[:\-–|]/i
];
var BREAKING_CATEGORIES = [
  "\u0639\u0627\u062C\u0644",
  "breaking",
  "breaking-news",
  "breaking news",
  "flash",
  "urgent",
  "actu-flash",
  "derni\xE8re minute",
  "\u062E\u0628\u0631 \u0639\u0627\u062C\u0644",
  "\u0623\u062E\u0628\u0627\u0631 \u0639\u0627\u062C\u0644\u0629"
];
function isSourceTaggedBreaking(title, categories = []) {
  for (const cat of categories) {
    const c = cat.toLowerCase().trim();
    if (BREAKING_CATEGORIES.some((bc) => c.includes(bc))) return true;
  }
  const t = title.trim();
  for (const pattern of BREAKING_TITLE_PREFIXES) {
    if (pattern.test(t)) return true;
  }
  return false;
}
