  "\u0628\u0646 \u0639\u0644\u064A": ["\u0632\u064A\u0646 \u0627\u0644\u0639\u0627\u0628\u062F\u064A\u0646 \u0628\u0646 \u0639\u0644\u064A (\u0631\u0626\u064A\u0633 \u062A\u0648\u0646\u0633 \u0627\u0644\u0633\u0627\u0628\u0642)", "\u0628\u0646 \u0639\u0644\u064A \u2014 \u0634\u062E\u0635 \u0622\u062E\u0631"],
  "\u0627\u0644\u0631\u0626\u064A\u0633 \u0627\u0644\u0633\u0627\u0628\u0642": null,
