async function uploadBase64ToPublicUrl(b64, mime = "image/jpeg") {
  const ext = mime.split("/")[1]?.split("+")[0] || "jpg";
  const buf = Buffer.from(b64, "base64");
  try {
    const blob = new Blob([buf], { type: mime });
    const fd = new FormData();
    fd.append("file", blob, `img.${ext}`);
    const r = await fetch("https://tmpfiles.org/api/v1/upload", {
      method: "POST",
      body: fd,
      signal: AbortSignal.timeout(12e3)
    });
    if (r.ok) {
      const d = await r.json();
      const u = d?.data?.url;
      if (u) return u.replace("tmpfiles.org/", "tmpfiles.org/dl/");
    }
  } catch (e) {
    console.warn("[img-upload] tmpfiles:", e.message);
  }
  try {
    const blob = new Blob([buf], { type: mime });
    const fd = new FormData();
    fd.append("file", blob, `img.${ext}`);
    const r = await fetch("https://0x0.st", {
      method: "POST",
      body: fd,
      signal: AbortSignal.timeout(12e3)
    });
    if (r.ok) {
      const url = (await r.text()).trim();
      if (url.startsWith("http")) return url;
    }
  } catch (e) {
    console.warn("[img-upload] 0x0.st:", e.message);
  }
  return null;
}
