import https from "https";
var NOMINATIM_BASE = "https://nominatim.openstreetmap.org";
var OVERPASS_BASE = "https://overpass-api.de/api/interpreter";
var UA = "DZ-Agent/1.0 (dz-gpt.vercel.app; contact@dzgpt.dz)";
function fetchJson(url) {
  return new Promise((resolve, reject) => {
    const opts = {
      headers: { "User-Agent": UA, "Accept": "application/json" }
    };
    https.get(url, opts, (res) => {
      let data = "";
      res.on("data", (d) => data += d);
      res.on("end", () => {
        try {
          resolve(JSON.parse(data));
        } catch {
          reject(new Error("JSON parse error: " + data.slice(0, 120)));
        }
      });
    }).on("error", reject);
  });
}
function postJson(url, body) {
  return new Promise((resolve, reject) => {
    const buf = Buffer.from(body);
    const opts = {
      method: "POST",
      headers: {
        "User-Agent": UA,
        "Content-Type": "application/x-www-form-urlencoded",
        "Content-Length": buf.length
      }
    };
    const u = new URL(url);
    const req = https.request({ hostname: u.hostname, path: u.pathname + u.search, ...opts }, (res) => {
      let data = "";
      res.on("data", (d) => data += d);
      res.on("end", () => {
        try {
          resolve(JSON.parse(data));
        } catch {
          reject(new Error("Overpass parse error"));
        }
      });
    });
    req.on("error", reject);
    req.write(buf);
    req.end();
  });
}
