      osmId: el.id,
      name: el.tags?.name || el.tags?.["name:ar"] || el.tags?.["name:fr"] || def.nameAr,
      nameAr: el.tags?.["name:ar"] || el.tags?.name || def.nameAr,
      lat: elat,
      lng: elng,
      phone: el.tags?.phone || el.tags?.["contact:phone"] || null,
