function buildGeoIndex() {
  const idx = [];
  for (const w of ALGERIA_GEO_DB) {
    idx.push({
      name: w.name,
      nameAr: w.nameAr,
      nameFr: w.nameFr,
      type: "\u0648\u0644\u0627\u064A\u0629",
      code: w.code,
      lat: w.lat,
      lng: w.lng,
      parent: null,
      aliases: w.aliases || []
    });
    for (const c of w.communes || []) {
      idx.push({
        name: c.name,
        nameAr: c.nameAr,
        nameFr: c.name,
        type: "\u0628\u0644\u062F\u064A\u0629",
        code: w.code,
        lat: c.lat,
        lng: c.lng,
        parent: w.nameAr,
        parentFr: w.nameFr,
        aliases: c.aliases || []
      });
    }
  }
  return idx;
}
function levenshtein2(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: m + 1 }, (_, i) => Array.from({ length: n + 1 }, (_2, j) => i === 0 ? j : j === 0 ? i : 0));
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] = a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
    }
  }
  return dp[m][n];
}
function normText(s) {
  return String(s).toLowerCase().replace(/[\u064B-\u065F\u0670]/g, "").replace(/أ|إ|آ/g, "\u0627").replace(/ة/g, "\u0647").replace(/ى/g, "\u064A").replace(/\s+/g, " ").trim();
}
function searchGeoLocation(query) {
  const idx = buildGeoIndex();
  const q = normText(query);
  if (!q) return { found: false, suggestions: [] };
  const scored = [];
  for (const entry of idx) {
    const candidates = [
      normText(entry.nameAr),
      normText(entry.nameFr || entry.name),
      normText(entry.name),
      ...(entry.aliases || []).map(normText)
    ];
    let bestScore = 0;
    for (const cand of candidates) {
      if (cand === q) {
        bestScore = 100;
        break;
      }
      if (cand.includes(q) || q.includes(cand)) {
        bestScore = Math.max(bestScore, 90);
        continue;
      }
      const maxLen = Math.max(q.length, cand.length);
      if (maxLen === 0) continue;
      const dist = levenshtein2(q, cand);
      const similarity = (maxLen - dist) / maxLen * 100;
      bestScore = Math.max(bestScore, similarity);
    }
    if (bestScore > 40) scored.push({ entry, score: bestScore });
  }
  scored.sort((a, b) => b.score - a.score);
  if (!scored.length) return { found: false, suggestions: [] };
  const top = scored[0];
  const suggestions = scored.slice(0, 3).map((s) => s.entry);
  if (top.score >= 90) {
    return { found: true, entry: top.entry, confidence: top.score, suggestions };
  }
  return { found: false, confidence: top.score, suggestions };
}

