async function deployAndWait({ branch, repoId = "1191199822", maxWaitMs = 18e4, onProgress, token }) {
  onProgress = onProgress || (() => {
  });
  const vToken = token || process.env.VERCEL_TOKEN;
  if (!vToken) throw new Error("VERCEL_TOKEN \u063A\u064A\u0631 \u0645\u0648\u062C\u0648\u062F");
  onProgress({ step: "trigger", label: "\u{1F680} \u0625\u0637\u0644\u0627\u0642 Vercel deployment..." });
  const { ok: ok2, data } = await vFetch("POST", "/v13/deployments", vToken, {
    name: "dz-gpt",
    gitSource: { type: "github", repoId, ref: branch },
    target: "production"
  }, 2e4);
  if (!ok2) throw new Error(`\u0641\u0634\u0644 \u0625\u0637\u0644\u0627\u0642 deployment: ${data.error?.message || data.message || "unknown"}`);
  const deployId = data.id;
  onProgress({ step: "trigger", label: `\u2705 deployment \u0645\u064F\u0637\u0644\u0642: ${deployId}`, done: true });
  const start = Date.now();
  const POLL = 8e3;
  while (Date.now() - start < maxWaitMs) {
    await new Promise((r) => setTimeout(r, POLL));
    const { ok: sOk, data: sData } = await vFetch("GET", `/v13/deployments/${deployId}`, vToken, null, 1e4);
    if (!sOk) continue;
    const state = sData.readyState;
    onProgress({ step: "poll", label: `\u23F3 Vercel state: ${state}` });
    if (state === "READY") {
      onProgress({ step: "ready", label: `\u2705 READY \u2014 ${LIVE_URL}`, done: true });
      return { id: deployId, state, url: LIVE_URL, raw: data.url };
    }
    if (state === "ERROR") {
      const errMsg = sData.errorMessage || "build error";
      throw new Error(`Vercel deployment \u0641\u0634\u0644: ${errMsg}`);
    }
    if (state === "CANCELED") throw new Error("Vercel deployment \u0645\u064F\u0644\u063A\u0649");
  }
  onProgress({ step: "timeout", label: "\u26A0\uFE0F \u0627\u0646\u062A\u0647\u062A \u0627\u0644\u0645\u0647\u0644\u0629 \u2014 \u0627\u0644\u0640 deployment \u0642\u062F \u064A\u0643\u0645\u0644 \u0644\u0627\u062D\u0642\u0627\u064B" });
  return { id: deployId, state: "BUILDING", url: LIVE_URL };
}
async function listDeployments({ projectId = DEFAULT_PROJECT, limit = 5, target, token } = {}) {
  const vToken = token || process.env.VERCEL_TOKEN;
  let path11 = `/v6/deployments?projectId=${projectId}&limit=${limit}`;
  if (target) path11 += `&target=${target}`;
  const { ok: ok2, data } = await vFetch("GET", path11, vToken);
  if (!ok2) return [];
  return (data.deployments || []).map((d) => ({
    id: d.uid,
    state: d.readyState,
    url: d.url ? `https://${d.url}` : LIVE_URL,
    branch: d.meta?.githubCommitRef,
    sha: d.meta?.githubCommitSha?.slice(0, 8),
    createdAt: d.createdAt
  }));
}
async function getDeploymentLogs(deploymentId, token) {
  const vToken = token || process.env.VERCEL_TOKEN;
  const { ok: ok2, data } = await vFetch("GET", `/v2/deployments/${deploymentId}/events?limit=100`, vToken);
  if (!ok2) return [];
  return (Array.isArray(data) ? data : []).map((e) => typeof e.payload === "object" ? e.payload.text : "").filter(Boolean);
}
async function listVercelEnvVars(projectId = DEFAULT_PROJECT, token) {
  const vToken = token || process.env.VERCEL_TOKEN;
  const { ok: ok2, data } = await vFetch("GET", `/v9/projects/${projectId}/env`, vToken);
  if (!ok2) return [];
  return (data.envs || []).map((e) => ({
    key: e.key,
    type: e.type,
    target: e.target,
    id: e.id,
    createdAt: e.createdAt
  }));
}
async function addVercelEnvVar({ projectId = DEFAULT_PROJECT, key: key2, value, target = ["production", "preview", "development"], type = "encrypted", token }) {
  const vToken = token || process.env.VERCEL_TOKEN;
  const { ok: ok2, status, data } = await vFetch("POST", `/v10/projects/${projectId}/env`, vToken, [{ key: key2, value, target, type }]);
  if (!ok2) throw new Error(`\u0641\u0634\u0644 \u0625\u0636\u0627\u0641\u0629 ${key2}: ${data.error?.message || status}`);
  return { key: key2, id: data[0]?.id, created: true };
}
async function getSyncStatus({ owner = "Nadirinfograph23", repo = "DZ-GPT", branch, projectId = DEFAULT_PROJECT, token }) {
  const vToken = token || process.env.VERCEL_TOKEN;
  const ghToken = process.env.GITHUB_TOKEN;
  const [ghR, depR] = await Promise.allSettled([
    fetch(`https://api.github.com/repos/${owner}/${repo}/git/ref/heads/${encodeURIComponent(branch)}`, {
      headers: { Authorization: `token ${ghToken}`, Accept: "application/vnd.github+json" },
      signal: AbortSignal.timeout(8e3)
    }).then((r) => r.json()).then((d) => d.object?.sha),
    listDeployments({ projectId, limit: 1, target: "production", token: vToken })
  ]);
  const ghSha = ghR.status === "fulfilled" ? ghR.value : null;
  const vercelDep = depR.status === "fulfilled" ? depR.value?.[0] : null;
  const vercelSha = vercelDep?.sha;
  const synced = ghSha && vercelSha && ghSha.startsWith(vercelSha);
  return {
    synced,
    status: !ghSha || !vercelSha ? "unknown" : synced ? "synced" : "out_of_sync",
    github: { sha: ghSha?.slice(0, 8), branch },
    vercel: { sha: vercelSha, state: vercelDep?.state, url: LIVE_URL },
    liveUrl: LIVE_URL
  };
}

