app.post("/api/dz-agent/github/pages/update", async (req, res) => {
  const tok = req.body.token ? sanitizeString2(req.body.token, 300) : process.env.GITHUB_TOKEN || "";
  if (!tok) return res.status(500).json({ error: "GITHUB_TOKEN \u063A\u064A\u0631 \u0645\u0636\u0628\u0648\u0637." });
  const { owner, repo, files, commitMessage = "Redeploy via DZ Agent \u{1F916}" } = req.body;
  if (!owner || !repo) return res.status(400).json({ error: "owner \u0648 repo \u0645\u0637\u0644\u0648\u0628\u0627\u0646." });
  if (!isValidGithubRepo2(`${owner}/${repo}`)) return res.status(400).json({ error: "Invalid repo format." });
  try {
    let commitSha = null;
    if (files?.length) {
      const { waitForMainBranch: waitBranch } = await Promise.resolve().then(() => (init_github_pages(), github_pages_exports));
      const branchInfo = await waitBranch(tok, owner, repo);
      const pushResult = await batchPushFiles(tok, owner, repo, files, commitMessage, branchInfo.branch);
      commitSha = typeof pushResult === "string" ? pushResult : pushResult?.sha || null;
    }
    const pagesResult = await enableGitHubPages(tok, owner, repo);
    const pagesInfo = await getPagesStatus(tok, owner, repo);
    return res.json({
      success: true,
      commitSha,
      siteUrl: pagesInfo?.url || `https://${owner}.github.io/${repo}`,
      pagesStatus: pagesInfo?.status || pagesResult?.status || "building",
      branch: pagesInfo?.branch || "main"
    });
  } catch (err) {
    console.error("[GH Pages:update]", err.message);
    return res.status(500).json({ error: err.message });
  }
});
