      const ex = await fetch(`https://api.github.com/repos/${targetRepo}/contents/${filePath}?ref=${targetBranch}`, { headers: ghH, signal: AbortSignal.timeout(8e3) });
      if (!ex.ok) return res.status(404).json({ error: `\u0627\u0644\u0645\u0644\u0641 "${filePath}" \u063A\u064A\u0631 \u0645\u0648\u062C\u0648\u062F.`, report: REPORT });
      const { sha: fileSha } = await ex.json();
