app.get("/api/tools/reverse-image", (req, res) => {
  const imageUrl = sanitizeString2(String(req.query.url || ""), 1e3).trim();
  if (!imageUrl) return res.status(400).json({ error: "url required" });
  const enc = encodeURIComponent(imageUrl);
  return res.json({
    links: [
      { name: "Google Lens", url: `https://lens.google.com/uploadbyurl?url=${enc}`, icon: "\u{1F50D}", color: "#4285F4" },
      { name: "Bing Visual", url: `https://www.bing.com/images/search?q=imgurl:${enc}&view=detailv2&iss=sbi`, icon: "\u{1F50E}", color: "#00809d" },
      { name: "Yandex", url: `https://yandex.com/images/search?url=${enc}&rpt=imageview`, icon: "\u{1F7E1}", color: "#f0330a" },
      { name: "TinEye", url: `https://www.tineye.com/search?url=${enc}`, icon: "\u{1F441}\uFE0F", color: "#72a81c" },
      { name: "SauceNAO", url: `https://saucenao.com/search.php?url=${enc}`, icon: "\u{1F3A8}", color: "#1a1a2e" }
    ]
  });
});
app.post("/api/tools/reverse-image-upload", async (req, res) => {
  const imageBase64 = String(req.body.imageBase64 || "");
  const mimeType = sanitizeString2(String(req.body.mimeType || "image/jpeg"), 50);
  if (!imageBase64) return res.status(400).json({ error: "imageBase64 required" });
  const base64Data = imageBase64.includes(",") ? imageBase64.split(",")[1] : imageBase64;
  const imgBuffer = Buffer.from(base64Data, "base64");
  const ext = mimeType.split("/")[1]?.replace("jpeg", "jpg") || "jpg";
  const filename = `dz-image.${ext}`;
  let publicUrl = null;
  try {
    const fd = new FormData();
    fd.append("file", new Blob([imgBuffer], { type: mimeType }), filename);
    const r = await fetch("https://0x0.st", {
      method: "POST",
      headers: { "User-Agent": "DZ-GPT/2.0" },
      body: fd,
      signal: AbortSignal.timeout(18e3)
    });
    if (r.ok) {
      const text = (await r.text()).trim();
      if (text.startsWith("http")) {
        publicUrl = text;
        console.log(`[ReverseUpload:0x0.st] ${publicUrl}`);
      }
    }
  } catch (e) {
    console.warn("[ReverseUpload:0x0.st] failed:", e.message);
  }
  if (!publicUrl) {
    try {
      const fd = new FormData();
      fd.append("file", new Blob([imgBuffer], { type: mimeType }), filename);
      const r = await fetch("https://tmpfiles.org/api/v1/upload", {
        method: "POST",
        headers: { "User-Agent": "DZ-GPT/2.0" },
        body: fd,
        signal: AbortSignal.timeout(15e3)
      });
      if (r.ok) {
        const d = await r.json();
        const raw = d?.data?.url || "";
        if (raw) {
          publicUrl = raw.replace("tmpfiles.org/", "tmpfiles.org/dl/");
          console.log(`[ReverseUpload:tmpfiles] ${publicUrl}`);
        }
      }
    } catch (e) {
      console.warn("[ReverseUpload:tmpfiles] failed:", e.message);
    }
  }
  if (!publicUrl) {
    try {
      const bin = `dzgpt-${Date.now()}`;
      const r = await fetch(`https://filebin.net/${bin}/${filename}`, {
        method: "POST",
        headers: {
          "Content-Type": mimeType,
          "User-Agent": "DZ-GPT/2.0",
          "Accept": "application/json"
        },
        body: imgBuffer,
        signal: AbortSignal.timeout(15e3)
      });
      if (r.ok) {
        publicUrl = `https://filebin.net/${bin}/${filename}`;
        console.log(`[ReverseUpload:filebin] ${publicUrl}`);
      }
    } catch (e) {
      console.warn("[ReverseUpload:filebin] failed:", e.message);
    }
  }
  if (!publicUrl) {
    return res.status(500).json({ error: "\u0641\u0634\u0644 \u0631\u0641\u0639 \u0627\u0644\u0635\u0648\u0631\u0629 \u0645\u0624\u0642\u062A\u0627\u064B \u2014 \u062C\u0631\u0651\u0628 \u0625\u062F\u062E\u0627\u0644 \u0631\u0627\u0628\u0637 URL \u0645\u0628\u0627\u0634\u0631\u0629 \u0628\u062F\u0644\u0627\u064B \u0645\u0646 \u0631\u0641\u0639 \u0627\u0644\u0645\u0644\u0641" });
  }
  const enc = encodeURIComponent(publicUrl);
  return res.json({
    url: publicUrl,
    links: [
      { name: "Google Lens", url: `https://lens.google.com/uploadbyurl?url=${enc}`, icon: "\u{1F50D}", color: "#4285F4" },
      { name: "Bing Visual", url: `https://www.bing.com/images/search?q=imgurl:${enc}&view=detailv2&iss=sbi`, icon: "\u{1F50E}", color: "#00809d" },
      { name: "Yandex", url: `https://yandex.com/images/search?url=${enc}&rpt=imageview`, icon: "\u{1F7E1}", color: "#f0330a" },
      { name: "TinEye", url: `https://www.tineye.com/search?url=${enc}`, icon: "\u{1F441}\uFE0F", color: "#72a81c" },
      { name: "SauceNAO", url: `https://saucenao.com/search.php?url=${enc}`, icon: "\u{1F3A8}", color: "#1a1a2e" }
    ]
  });
});
