async function waitForHordeJob(jobId, maxWaitMs = 72e3, maxWaitEstimateSec = 9999) {
  const BASE7 = "https://stablehorde.net/api/v2";
  const H = { "Client-Agent": "DZ-GPT:1.0:dz-gpt.vercel.app", "apikey": process.env.STABLE_HORDE_KEY || "0000000000" };
  const start = Date.now();
  let polls = 0;
  while (Date.now() - start < maxWaitMs) {
    await new Promise((r) => setTimeout(r, polls < 4 ? 5e3 : 8e3));
    polls++;
    try {
      const chk = await fetch(`${BASE7}/generate/check/${jobId}`, { headers: H, signal: AbortSignal.timeout(8e3) });
      if (!chk.ok) continue;
      const cd = await chk.json();
      console.log(`[horde:p${polls}] done=${cd.done} wait=${cd.wait_time}s q=${cd.queue_position}`);
      if (cd.faulted || cd.is_possible === false) break;
      if (polls === 1 && !cd.done && (cd.wait_time || 0) > maxWaitEstimateSec) {
        console.warn(`[horde] wait_time=${cd.wait_time}s > ${maxWaitEstimateSec}s limit \u2014 cancelling job`);
        fetch(`${BASE7}/generate/status/${jobId}`, { method: "DELETE", headers: H }).catch(() => {
        });
        return null;
      }
      if (cd.done) {
        const st = await fetch(`${BASE7}/generate/status/${jobId}`, { headers: H, signal: AbortSignal.timeout(15e3) });
        if (!st.ok) break;
        const sd = await st.json();
        const img = sd.generations?.[0]?.img;
        if (img) return img;
        break;
      }
    } catch (e) {
      console.warn("[horde:poll]", e.message);
    }
  }
  return null;
}
async function hordeSubmitImg2Img(imgB64, prompt, negPrompt, strength) {
  const BASE7 = "https://stablehorde.net/api/v2";
  const H = { "Content-Type": "application/json", "Client-Agent": "DZ-GPT:1.0:dz-gpt.vercel.app", "apikey": process.env.STABLE_HORDE_KEY || "0000000000" };
  const r = await fetch(`${BASE7}/generate/async`, {
    method: "POST",
    headers: H,
    body: JSON.stringify({
      prompt: `${prompt.trim()} ### ${negPrompt || "ugly, blurry, low quality, distorted, deformed"}`,
      params: { n: 1, steps: 25, width: 512, height: 512, sampler_name: "k_euler_a", denoising_strength: Math.max(0.3, Math.min(1, Number(strength) || 0.75)), cfg_scale: 7.5 },
      source_image: imgB64,
      source_processing: "img2img",
      models: ["stable_diffusion"],
      shared: true,
      r2: false
    }),
    signal: AbortSignal.timeout(1e4)
  });
  if (!r.ok) {
    console.warn("[horde:submit]", r.status);
    return null;
  }
  const d = await r.json();
  return d.id || null;
}
