function _ttsSplitText(text, max = 190) {
  const parts = [];
  let rem = text.trim();
  while (rem.length > 0) {
    if (rem.length <= max) {
      parts.push(rem);
      break;
    }
    let cut = rem.lastIndexOf(" ", max);
    if (cut <= 0) cut = max;
    parts.push(rem.slice(0, cut));
    rem = rem.slice(cut).trim();
  }
  return parts;
}
